--
-- Table structure for table `templates`
--

CREATE TABLE `templates` (
  `id` int(11) NOT NULL,
  `doc_id` varchar(55) NOT NULL,
  `name` text NOT NULL,
  `creation_type` enum('manual','upload') NOT NULL,
  `contract_body` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `email_subject` text,
  `email_message` text,
  `signature_config` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `text_config` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin,
  `created_by` int(11) DEFAULT NULL,
  `document_status` enum('draft','published','archived') NOT NULL,
  `date_updated` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `date_created` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

